mapper.select:
select f.FileTitle as cpFileTitle, flow.FlowName as cpFlowName, fa.ActName as cpActName, u.U_Name as cpSendName, t.TaskName as cpTaskName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode,
from SYS_CoordinationProcess cp left join SYS_FlowActivity fa on fa.ActID=cp.CP_ActID left join SYS_Task t on t.TaskID=cp.CP_TaskID left join SYS_Flow flow on flow.FlowID=cp.CP_FlowID left join Sys_File f on f.FileID=cp.CP_FileID left join Sys_User u on u.U_Id=cp.CP_SendUser left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract
cp.CP_User=#{params.userId}
and cp.cp_name like concat('%',#{params.cpName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and fa.ActName like concat('%',#{params.cpActName},'%')
and f.FileTitle like concat('%',#{params.cpFileTitle},'%')
and f.FileTitle like concat('%',#{params.cpFileTitle},'%')
and u.U_Name like concat('%',#{params.cpSendUser},'%')
and cp.Te_Id = #{params.teId}
order by cp.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}
